import java.io.*;
import java.util.*;
public class G{
    public static void main(String[] args) {
        InputStream inputStream = System.in;
        OutputStream outputStream = System.out;
        InputReader in = new InputReader(inputStream);
        PrintWriter out = new PrintWriter(outputStream);
        TaskE solver = new TaskE();
        solver.solve(1, in, out);
        out.flush();out.close();
    }
    static class TaskE {
        class MinCostMaxFlow{
            ArrayList<Edge> al[];
            Edge ja[][]; 
            int N , S , T , maxFlow ; int minCost;
            final int gmax = Integer.MAX_VALUE / 100;

            class Edge{
                int u , flow, rid, cost;
                Edge(int a, int b, int c, int d){u = a; flow = b; cost = c; rid = d;}
            }

            void addEdge(int u , int v , int flow , int cost){
                int lu = al[u].size(), lv = al[v].size();
                al[u].add(new Edge(v, flow, cost, lv)); 
                al[v].add(new Edge(u, 0, -cost, lu));   
            }

            void convertToArray(){
                ja = new Edge[N][];
                for(int i = 0; i < N; i++){
                    int sz = al[i].size();
                    ja[i] = new Edge[sz];
                    for(int j = 0; j < sz; j++){
                        ja[i][j] = al[i].get(j);
                    }
                    al[i].clear();
                }
            }

            MinCostMaxFlow(int n , int source , int sink){
                N = n; S = source; T = sink; maxFlow = 0; minCost = 0;
                al = new ArrayList[N];
                for(int i = 0; i < N; i++){
                    al[i] = new ArrayList<>();
                }
            }

            int[] dist, prv, prve;

            boolean bellmanFord(){
                dist = new int[N];
                prv = new int[N];
                prve = new int[N];
                Arrays.fill(dist, gmax);
                dist[S] = 0;
                for(int i = 0; i < N-1; i++){
                    boolean updated = false;
                    for(int u = 0; u < N; u++){
                        if(dist[u] == gmax) continue;
                        for(int e = 0; e < ja[u].length; e++){
                            Edge edge = ja[u][e];
                            if(edge.flow == 0) continue;
                            int v = edge.u;
                            int nd = dist[u] + edge.cost;
                            if(nd < dist[v]){
                                dist[v] = nd;
                                prv[v] = u;
                                prve[v] = e;
                                updated = true;
                            }
                        }
                    }
                    if(!updated) break;
                }
                return dist[T] != gmax;
            }

            int augment(){
                int p = T, min = gmax;
                while(p != S){
                    int u = prv[p], e = prve[p];
                    min = Math.min(min, ja[u][e].flow);
                    p = u;
                }
                p = T;
                while(p != S){
                    int u = prv[p], e = prve[p];
                    ja[u][e].flow -= min;
                    ja[p][ja[u][e].rid].flow += min;
                    p = u;
                }
                maxFlow += min;
                return min;
            }

            void calBellmanFord(){
                while(bellmanFord()){
                    minCost += dist[T] * augment();
                }
            }
        }
        int n , m, k, c, d, a[], f[];
       public void solve(int testNumber, InputReader in, PrintWriter out) {
        n = in.nextInt(); m = in.nextInt(); k = in.nextInt(); c = in.nextInt(); d= in.nextInt();
        int maxl = n + k, T = n * maxl + 1;
        MinCostMaxFlow ans = new MinCostMaxFlow(T + 1, 0, T);
        a = new int[k + 1]; f = new int[n + 1];
        for(int i = 1; i <= k; i++){
            a[i] = in.nextInt();
            f[a[i]]++;
        }
        for(int i = 1; i <= n; i++){
            if(f[i] == 0)continue;
            ans.addEdge(0 , i , f[i], 0);
        }
        for(int i = 2; i <= n; i++){
            for(int l = 0; l < maxl - 1; l++){
                ans.addEdge(l * n + i , (l + 1) * n + i, k, c);
            }
        }
        for(int i = 1; i <= m; i++){
            int a = in.nextInt(), b = in.nextInt();
            for(int l = 0; l < maxl - 1; l++){
                for(int p = 1; p <= k; p++){
                    if(a != 1)
                        ans.addEdge(n * l + a, n * (l + 1) + b, 1, d * (2 * p - 1) + c);
                    if(b != 1)
                        ans.addEdge(n * l + b, n * (l + 1) + a, 1, d * (2 * p - 1) + c);
                }
            } 
        }
        for(int l = 1; l < maxl; l++){
            ans.addEdge(l * n + 1, T, k, 0);
        }
        ans.convertToArray();
        ans.calBellmanFord();
        if(ans.maxFlow != k){
            out.println("BUG");
        }else{
            out.println((int)ans.minCost);
        }
      }
    }
    static class InputReader {
        BufferedReader br;
        StringTokenizer st;
        public InputReader(InputStream stream) {
            br = new BufferedReader(new InputStreamReader(stream));
            st = null;
        }

        String next() {
            while (st == null || !st.hasMoreTokens()) {
                String s = null;
                try {
                    s = br.readLine();
                } catch (IOException e) {
                    e.printStackTrace();
                }
                if (s == null)
                    return null;
                st = new StringTokenizer(s);
            }
            return st.nextToken();
        }

        boolean hasMoreTokens() {
            while (st == null || !st.hasMoreTokens()) {
                String s = null;
                try {
                    s = br.readLine();
                } catch (IOException e) {
                    e.printStackTrace();
                }
                if (s == null)
                    return false;
                st = new StringTokenizer(s);
            }
            return true;
        }

        public int nextInt() {
            return Integer.parseInt(next());
        }
        public long nextLong() {
            return Long.parseLong(next());
        }
        public double nextDouble() {
            return Double.parseDouble(next());
        }
    }
}
